"""Dependency-free static, privacy-safe public dashboard builder."""
import json, html
from pathlib import Path
D=json.loads(Path('data/evidence.json').read_text())
e=html.escape
nav=[('index','Executive summary')]+[(p['id'],p['title']) for p in D['pages']]+[('sources','Sources & methodology')]
def shell(id,title,content):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Privacy-safe, evidence-linked Los Angeles net lease property research. Unknown financial values are withheld."><title>{e(title)} · Jack / Property research</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="mark">J.</span> JACK<span class="brand-sub">PROPERTY INTELLIGENCE</span></a><div class="nav-label">RESEARCH WORKSPACE</div><nav>{''.join(f'<a {"aria-current=page" if key==id else ""} href="{key}.html"><span>{str(i+1).zfill(2)}</span>{e(label)}</a>' for i,(key,label) in enumerate(nav))}<a href="report/index.html"><span>&#9733;</span>Canonical decision file</a></nav><div class="privacy"><span>◈</span><b>Privacy by design</b><p>Asset A · anonymized<br>No owner or parcel identifiers</p></div></aside><div class="workspace"><header><span>RESEARCH / LOS ANGELES</span><span class="stamp">● &nbsp; Evidence review · 06 Nov 2026</span></header><main id="main">{content}</main><footer>Independent decision-support research. Not an appraisal, legal opinion or personalized financial advice.<br>Static evidence snapshot · No tracking, forms, third-party assets or private documents · <a href="sources.html">Methodology & limitations</a></footer></div></body></html>'''
def table(p):
    heads=p['columns']+['Evidence','Official source']
    out='<div class="table-wrap"><table><caption>'+e(p['title'])+' · evidence register</caption><thead><tr>'+''.join('<th scope="col">'+e(c)+'</th>' for c in heads)+'</tr></thead><tbody>'
    for r in p['rows']:
        s=D['sources'][r['source']]; status=r['status']; cls='verified' if status=='Verified' else 'analysis' if status=='Analysis' else 'unknown'
        out+='<tr>'+''.join('<td'+(' class="empty" aria-label="Unverified value; intentionally blank"' if c=='' else '')+'>'+e(c)+'</td>' for c in r['cells'])+f'<td><span class="badge {cls}">{e(status)}</span></td><td><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["label"])} ↗</a></td></tr>'
    return out+'</tbody></table></div>'
for p in D['pages']:
    intro=f'<div class="eyebrow">{e(p["kicker"])}</div><h1>{e(p["title"])}</h1><p class="lede">{e(p["description"])}</p><div class="legend"><span class="badge verified">Verified</span> Source-matched observation <span class="badge analysis">Analysis</span> Conditional interpretation <span class="badge unknown">Unverified</span> Missing evidence</div>'
    Path(p['id']+'.html').write_text(shell(p['id'],p['title'],intro+table(p)))
import sys as _sys, os as _os
_sys.path.insert(0, _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))))
import data.report_data as _rd
_counts=_rd.counts()
portal=f'''<div class="eyebrow">CANONICAL DECISION FILE &middot; EVIDENCE SNAPSHOT 2026-11-07</div><h1>One property. One decision.<br><span>One reconciled file.</span></h1><p class="lede">A Jack in the Box triple-net property in Central Los Angeles, primary term expiring 2030&ndash;2035. Six parallel research layers were merged, every decisive figure was re-read on its official publisher, and the conflicts between the layers were resolved in the open.</p><div class="hero-note"><span class="badge verified">RECOMMENDATION</span><h2>Sell before expiry &mdash; extend first only if the tenant commits in writing.</h2><p>Selling now has the highest worst-case present value of every strategy tested (11.62 R, against 1.18 R for renewing to a 2030 expiry). Renewing with a contracting tenant ranks last in both the base and the pessimistic scenarios. If, and only if, the tenant signs a long extension now, extend and then sell the lengthened lease.</p><a class="button" href="report/index.html">Open the decision file <span>&rarr;</span></a><a class="quiet" href="report/executive-summary.html">Read the executive summary &rarr;</a><a class="quiet" href="report/flagged.html">See what could not be verified &rarr;</a></div><div class="section-heading"><h2>The four numbers that frame it</h2><span>Official sources. Dated. Re-read 7 Nov 2026.</span></div><div class="cards"><article><div class="eyebrow">DEMAND / LA COUNTY</div><strong>&minus;3.2%</strong><p>Population change, 2020 estimates base to 1 July 2025. The measured trend, not a forecast.</p><a href="https://www.census.gov/quickfacts/fact/table/losangelescountycalifornia/PST045224">Census QuickFacts &nearr;</a></article><article><div class="eyebrow">LABOUR / LA METRO</div><strong>4.4%</strong><p>Unemployment, September 2026, preliminary and not seasonally adjusted &mdash; while the labour force also shrank.</p><a href="https://www.bls.gov/eag/eag.ca_losangeles_msa.htm">BLS Economy at a Glance &nearr;</a></article><article><div class="eyebrow">TENANT / SYSTEM</div><strong>&minus;1.1%</strong><p>Same-store sales, Q3 FY2026, brand-wide. Not this restaurant's performance.</p><a href="https://www.sec.gov/Archives/edgar/data/807882/000080788226000091/jack-20260705.htm">SEC Form 10-Q &nearr;</a></article><article><div class="eyebrow">COST FLOOR / CALIFORNIA</div><strong>$20.00</strong><p>Fast-food minimum wage per hour, which applies to franchisees as well as the brand.</p><a href="https://www.dir.ca.gov/dlse/Fast-Food-Minimum-Wage-FAQ.htm">CA DIR &nearr;</a></article></div><section class="split"><div><div class="eyebrow">HOW THIS FILE IS BUILT</div><h2>{_counts['total']} rows. {_counts['official_sources']} official sources.<br>Nothing guessed.</h2><p>Every published observation carries its publisher, period, geography and verification status. {_counts['verified-now']} rows were re-read on the publisher's own page during the integration; the rest carry official or SEC links and were read when captured. Eight industry cap-rate rows are shown separately and never scored as verified.</p><p>Anything that could not be confirmed from an official source is blank, and it is listed on the Flagged for Review page with the specific action that would close it &mdash; together with the twelve conflicts found between the earlier layers and how each was resolved.</p></div><div class="callout"><h3>Privacy by design</h3><p>The property is <b>Asset A</b>. No address, parcel number, owner, tenant officer or contact detail appears anywhere in this site or its data. No forms, cookies, analytics, third-party scripts or external fonts.</p><p>There is no valuation, no cap rate asserted as fact, and no price target: the rent and basis were never supplied.</p><a href="report/methodology.html">Method, privacy and limits &rarr;</a><a href="report/flagged.html">Flagged for review &rarr;</a></div></section><div class="section-heading"><h2>Browse by category</h2><span>The full decision file</span></div><div class="route-grid"><a href="report/property.html"><b>The asset</b><p>Anonymised profile, NNN cost allocation, lease disclosures, the 15-field Input Register.</p>Open &rarr;</a><a href="report/market.html"><b>The market</b><p>Population, income, housing, jobs, prices, property tax and regulation &mdash; row by row.</p>Open &rarr;</a><a href="report/tenant.html"><b>Tenant credit</b><p>Unit counts, closures, same-store sales and the lease terms the issuer discloses.</p>Open &rarr;</a><a href="report/projections.html"><b>Projections</b><p>Three scenarios, a sourced discount anchor, every assumption exposed.</p>Open &rarr;</a><a href="report/risk.html"><b>Risk</b><p>15 business-as-usual risks and 7 black-swan events, scored and mitigated.</p>Open &rarr;</a><a href="report/decision.html"><b>Decision</b><p>Six strategies ranked by worst case, tax mechanics, triggers and a dated action plan.</p>Open &rarr;</a></div><div class="callout"><h3>Earlier parallel layers (archive)</h3><p>Six sessions worked this repository in parallel on 6 November 2026. Their outputs are preserved and remain reachable below, but where they disagree with the decision file, the decision file is canonical &mdash; see the <a href="report/flagged.html#reconciliation">reconciliation log</a>.</p><p><a href="report/index.html">Canonical decision file (report/)</a> &middot; <a href="docs/index.html">docs/ research dashboard</a> &middot; <a href="analysis/index.html">analysis/ deep dive</a> &middot; <a href="brief/index.html">brief/ decision brief</a> &middot; <a href="pages/index.html">pages/ sourced dashboard</a> &middot; <a href="decision-file/index.html">decision-file/ verified file</a></p></div>'''
Path('index.html').write_text(shell('index','Decision file',portal))
src={'title':'Official source register','columns':['Publisher / document','Type','Reviewed','Use and limits'],'rows':[dict(cells=[s['label'],s['type'],s['checked'],'Primary source checked for published observations; not a property appraisal.'],status='Verified',source=k) for k,s in D['sources'].items()]}
content='''<div class="eyebrow">08 / AUDIT TRAIL</div><h1>Sources & methodology</h1><p class="lede">Evidence first. Interpretation second. Unknowns stay unknown.</p><section class="callout"><h2>Verification standard</h2><p>Each Verified row was manually matched to the linked government publication or issuer release on 6 November 2026. Verified means the source reports the observation—not that it predicts this property. Issuer reports are labeled separately from government data.</p><p>Analysis rows are our conditional reasoning. Their official links support background context only; they do not endorse the recommendation. Unverified rows contain no invented value; links are research routes or explicitly limited context, not proof of missing facts.</p><p>QuickFacts observations use different vintages, geography and survey periods. ACS estimates have sampling error; no tract estimates or margins of error were obtained. The BLS October 5, 2026 summary uses unadjusted data and may be revised. No model has been trained or back-tested; no causal claim about property value is made.</p><h3>Privacy and publication boundary</h3><p>Asset A and Owner A are placeholders. No addresses, parcel IDs, owner names, contact details, financial accounts or private lease records are collected or published. No analytics, third-party embeds or external scripts are used. GitHub hosting may retain standard access logs. Public source links open their publishers’ websites.</p><h3>Reproducibility and maintenance</h3><p>Public evidence is stored in data/evidence.json; scripts/build.py generates every page. scripts/validate.py checks table provenance, local links and blank-value status. Source values were reviewed manually; automated validation does not assert live external availability or semantic verification. This is a fixed snapshot, not a live data feed. Refresh official releases and reassess geographic fit before acting.</p><p>Initial repository review found only a README and no historical analysis or personal data. No hidden property records or private evidence were inferred. Missing private documents cannot be supplied through autonomous public research.</p></section>'''+table(src)
Path('sources.html').write_text(shell('sources','Sources & methodology',content))
